import java.util.*;
class Main {
  public static void main(String[] args) {
    Map<Character, Integer> m = new HashMap<>();
    for (char c : "aba".toCharArray()) m.merge(c, 1, Integer::sum);
    System.out.println(m.get('a') + " " + m.get('b'));
  }
}

